import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-joins-l3-001', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL', question: 'When does PostgreSQL automatically add an implicit LATERAL to a FROM item?', options: ['Never — LATERAL must be explicit', 'When a set-returning function in FROM references another FROM item', 'When using CROSS JOIN', 'When the subquery has LIMIT'], correctAnswer: 1, explanation: 'Set-returning functions (like UNNEST, generate_series) in FROM that reference other FROM items get an implicit LATERAL. Regular subqueries require explicit LATERAL.', tags: ['lateral', 'implicit', 'set-returning'] },
  { id: 'pg-joins-l3-002', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'What are the three physical join strategies PostgreSQL can use?', options: ['LEFT, RIGHT, FULL', 'Nested Loop, Hash Join, Merge Join', 'Index, Sequential, Bitmap', 'Sort, Filter, Aggregate'], correctAnswer: 1, explanation: 'Nested Loop iterates outer rows and probes inner for each. Hash Join builds a hash table. Merge Join sorts both sides and merges. The planner picks based on statistics and cost.', tags: ['join-strategies', 'planner', 'physical'] },
  { id: 'pg-joins-l3-003', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'When does PostgreSQL prefer a Merge Join?', options: ['When tables are small', 'When both inputs are already sorted (e.g., from index scans) on the join keys', 'When there is no index', 'Always for equi-joins'], correctAnswer: 1, explanation: 'Merge Join requires sorted input. If both sides can provide sorted data (via index scans or explicit sorts), merge join can be very efficient, especially for large datasets.', tags: ['merge-join', 'sorted', 'index'] },
  { id: 'pg-joins-l3-004', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'When does PostgreSQL prefer a Hash Join?', options: ['When tables are tiny', 'When the smaller table fits in work_mem and there is no useful sort order on the join keys', 'When using LEFT JOIN only', 'When columns are indexed'], correctAnswer: 1, explanation: 'Hash Join is efficient when one side fits in work_mem. It builds a hash table from the smaller relation. No pre-sorting is required. It only works for equi-joins.', tags: ['hash-join', 'work-mem', 'equi-join'] },
  { id: 'pg-joins-l3-005', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'Can PostgreSQL perform a Hash Right Join or Hash Full Join?', options: ['No, only Hash Inner Join', 'Yes, PostgreSQL supports hash joins for all join types including right, full, and anti joins', 'Only with parallel query', 'Only for inner and left joins'], correctAnswer: 1, explanation: 'PostgreSQL can use hash joins for INNER, LEFT, RIGHT, FULL, SEMI, and ANTI joins. The hash table is always built from the inner (right) side.', tags: ['hash-join', 'join-types', 'versatility'] },
  { id: 'pg-joins-l3-006', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Parallel Join', question: 'How does PostgreSQL parallelize hash joins?', options: ['It cannot parallelize joins', 'Parallel workers build a shared hash table, then each worker probes it with their portion of the outer table', 'Each worker gets its own hash table', 'Only the outer table is parallelized'], correctAnswer: 1, explanation: 'In a parallel hash join, multiple workers cooperate to build a single shared hash table, then each worker independently probes it with different chunks of the outer table.', codeSnippet: 'SET max_parallel_workers_per_gather = 4;\nEXPLAIN ANALYZE\nSELECT * FROM big_a JOIN big_b ON big_a.id = big_b.a_id;', tags: ['parallel-hash-join', 'shared-hash', 'parallel-query'] },
  { id: 'pg-joins-l3-007', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Anti-join', question: 'In EXPLAIN output, how does an anti-join appear?', options: ['As Anti Join', 'As a Hash Anti Join, Merge Anti Join, or Nested Loop Anti Join node', 'As NOT IN', 'As LEFT JOIN with Filter'], correctAnswer: 1, explanation: 'PostgreSQL converts NOT EXISTS and NOT IN into anti-join plan nodes. They appear as "Hash Anti Join", "Merge Anti Join", etc., which are efficient single-pass operations.', tags: ['anti-join', 'explain', 'plan-node'] },
  { id: 'pg-joins-l3-008', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Semi-join', question: 'In EXPLAIN output, how does a semi-join appear?', options: ['As Semi Join', 'As a Hash Semi Join, Merge Semi Join, or Nested Loop Semi Join node', 'As EXISTS', 'As DISTINCT'], correctAnswer: 1, explanation: 'PostgreSQL converts EXISTS and IN into semi-join plan nodes (Hash Semi Join, etc.). A semi-join returns the outer row as soon as the first match is found.', tags: ['semi-join', 'explain', 'plan-node'] },
  { id: 'pg-joins-l3-009', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery Flattening', question: 'What is "subquery flattening" (or pull-up)?', options: ['Removing subqueries entirely', 'The optimizer converts a subquery into a join for better plan choices', 'Flattening nested CTEs', 'Converting correlated to uncorrelated subqueries'], correctAnswer: 1, explanation: 'Subquery flattening converts subqueries in FROM or WHERE into equivalent joins. This gives the optimizer more freedom to choose join order and strategy.', tags: ['subquery-flattening', 'pull-up', 'optimizer'] },
  { id: 'pg-joins-l3-010', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery Flattening', question: 'When can PostgreSQL NOT flatten a subquery?', options: ['When it has no WHERE clause', 'When it contains LIMIT, OFFSET, volatile functions, FOR UPDATE, or aggregates that prevent safe transformation', 'When it references only one table', 'When it has an alias'], correctAnswer: 1, explanation: 'Subqueries with LIMIT, OFFSET, aggregate functions, volatile functions, FOR UPDATE, or DISTINCT cannot always be safely flattened into joins by the optimizer.', tags: ['subquery-flattening', 'limitations', 'optimizer'] },
  { id: 'pg-joins-l3-011', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'Can a recursive CTE reference itself more than once in the recursive term?', options: ['Yes, multiple self-references are fine', 'No, the recursive term can reference the recursive CTE name only once', 'Only with UNION ALL', 'Only in PostgreSQL 15+'], correctAnswer: 1, explanation: 'The SQL standard and PostgreSQL restrict the recursive term to reference the recursive CTE exactly once. Multiple references or using it in a subquery are not allowed.', tags: ['recursive-cte', 'restriction', 'single-reference'] },
  { id: 'pg-joins-l3-012', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'Can you use LEFT JOIN in the recursive term of a recursive CTE?', options: ['Yes, any join type is allowed', 'No, only INNER JOIN (or equivalent) on the recursive reference is allowed', 'Only RIGHT JOIN', 'Only CROSS JOIN'], correctAnswer: 1, explanation: 'The recursive term cannot use LEFT JOIN, RIGHT JOIN, or FULL JOIN on the recursive self-reference. Only INNER JOIN is permitted to ensure termination.', tags: ['recursive-cte', 'restriction', 'join-type'] },
  { id: 'pg-joins-l3-013', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'Can you use aggregate functions in the recursive term of a recursive CTE?', options: ['Yes, aggregates work normally', 'No, GROUP BY and aggregate functions are not allowed in the recursive term', 'Only COUNT', 'Only with HAVING'], correctAnswer: 1, explanation: 'The recursive term cannot use GROUP BY, HAVING, aggregate functions, or set-returning functions. These restrictions ensure well-defined recursion behavior.', tags: ['recursive-cte', 'restriction', 'aggregates'] },
  { id: 'pg-joins-l3-014', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL Performance', question: 'How does LATERAL JOIN compare to window functions for top-N-per-group?', options: ['Window functions are always faster', 'LATERAL is often faster when there is an index because it does index lookups per group; window functions scan the entire table', 'They always have the same performance', 'LATERAL cannot do top-N'], correctAnswer: 1, explanation: 'LATERAL with ORDER BY + LIMIT per group uses index lookups (O(groups * N * log(rows))). Window functions (ROW_NUMBER) scan all rows first. LATERAL wins with good indexes and many groups.', tags: ['lateral', 'window-function', 'performance-comparison'] },
  { id: 'pg-joins-l3-015', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Hash Join', question: 'What happens when the hash table for a Hash Join exceeds work_mem?', options: ['The query fails', 'PostgreSQL uses "batched" hash join, spilling portions to disk and processing in multiple passes', 'It switches to nested loop', 'It increases work_mem automatically'], correctAnswer: 1, explanation: 'When the hash table exceeds work_mem, PostgreSQL partitions the data into batches. Some batches are kept in memory, others spill to disk. Multiple passes process all batches.', tags: ['hash-join', 'batched', 'work-mem'] },
  { id: 'pg-joins-l3-016', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Merge Join', question: 'What is the advantage of Merge Join over Hash Join for very large datasets?', options: ['Merge Join is always faster', 'Merge Join can handle datasets larger than work_mem efficiently if the data is pre-sorted, without needing to spill to disk', 'Hash Join is always better for large data', 'They handle large data identically'], correctAnswer: 1, explanation: 'Merge Join streams through sorted data without materializing. If indexes provide the sort order, it can process arbitrarily large datasets with minimal memory.', tags: ['merge-join', 'large-datasets', 'memory'] },
  { id: 'pg-joins-l3-017', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Nested Loop', question: 'What is a "parameterized" nested loop join?', options: ['A join with query parameters', 'A nested loop where the inner scan uses the outer row\'s value as a parameter for an index lookup', 'A join with prepared statements', 'A loop with variable batch size'], correctAnswer: 1, explanation: 'In a parameterized nested loop, each outer row provides a value that drives an index scan on the inner table. This is efficient when the outer table is small and there is a good index on the inner table.', tags: ['nested-loop', 'parameterized', 'index-scan'] },
  { id: 'pg-joins-l3-018', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Ordering', question: 'What is the Genetic Query Optimizer (GEQO) in PostgreSQL?', options: ['A DNA-based algorithm', 'A genetic algorithm used for join ordering when the number of tables exceeds geqo_threshold (default 12)', 'A query validator', 'An index suggestion tool'], correctAnswer: 1, explanation: 'When the number of FROM items exceeds geqo_threshold, PostgreSQL uses a genetic algorithm (GEQO) for join ordering instead of exhaustive search, as the search space grows factorially.', codeSnippet: 'SET geqo_threshold = 12; -- default\n-- For 12+ tables, uses genetic algorithm\n-- For fewer tables, uses dynamic programming', tags: ['geqo', 'join-ordering', 'optimization'] },
  { id: 'pg-joins-l3-019', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'CTE Optimization', question: 'When should you use MATERIALIZED on a CTE?', options: ['Always for best performance', 'When the CTE is referenced multiple times and you want to avoid redundant computation, or when you need an optimization fence', 'Never — NOT MATERIALIZED is always better', 'Only for recursive CTEs'], correctAnswer: 1, explanation: 'MATERIALIZED is useful when: 1) the CTE is referenced multiple times (avoids recomputation), 2) you want to prevent predicate pushdown that might worsen performance, or 3) you need consistent results across multiple references.', tags: ['cte', 'materialized', 'when-to-use'] },
  { id: 'pg-joins-l3-020', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery Types', question: 'What is a "lateral cross join" and when does PostgreSQL generate one internally?', options: ['A special syntax', 'When a set-returning function in SELECT (like UNNEST) is internally converted to a LATERAL CROSS JOIN in FROM', 'When two tables share no columns', 'When LATERAL is used with CROSS JOIN explicitly'], correctAnswer: 1, explanation: 'Set-returning functions in SELECT are internally converted to LATERAL CROSS JOIN in FROM. For example, SELECT unnest(array_col) FROM t is transformed to FROM t, LATERAL unnest(t.array_col).', tags: ['lateral-cross-join', 'set-returning', 'internal'] },
  { id: 'pg-joins-l3-021', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Writable CTE', question: 'Can writable CTEs see each other\'s changes?', options: ['Yes, they execute sequentially', 'No, all CTEs in a statement share the same snapshot and cannot see each other\'s modifications', 'Only INSERT CTEs can see DELETE CTEs', 'It depends on the order'], correctAnswer: 1, explanation: 'All sub-statements in a WITH clause share the same snapshot of the underlying tables. A DELETE CTE cannot see rows inserted by an INSERT CTE in the same statement.', tags: ['writable-cte', 'snapshot', 'isolation'] },
  { id: 'pg-joins-l3-022', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Elimination', question: 'What is "join elimination" by the optimizer?', options: ['Removing all joins from a query', 'Removing unnecessary joins when the joined table does not affect the result (e.g., joining on a unique/FK column but not selecting from it)', 'Converting joins to subqueries', 'Removing duplicate joins'], correctAnswer: 1, explanation: 'If a LEFT JOIN references a unique column but no columns from the joined table are used in SELECT/WHERE/etc., PostgreSQL can eliminate the join entirely, improving performance.', tags: ['join-elimination', 'optimization', 'unnecessary-join'] },
  { id: 'pg-joins-l3-023', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you perform a "conditional join" where the join table depends on a column value?', options: ['Using IF statements', 'Using LATERAL with CASE or UNION ALL, or joining both tables and using COALESCE', 'It is not possible in SQL', 'Using dynamic SQL only'], correctAnswer: 1, explanation: 'LATERAL can select from different tables based on a condition. Alternatively, LEFT JOIN both possible tables and use COALESCE to pick the right one.', codeSnippet: 'SELECT o.id,\n  COALESCE(dom.address, intl.address) AS shipping_address\nFROM orders o\nLEFT JOIN domestic_addresses dom\n  ON o.address_id = dom.id AND o.is_domestic\nLEFT JOIN international_addresses intl\n  ON o.address_id = intl.id AND NOT o.is_domestic;', tags: ['conditional-join', 'coalesce', 'lateral'] },
  { id: 'pg-joins-l3-024', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery Performance', question: 'Why can correlated subqueries sometimes perform better than expected?', options: ['They always perform poorly', 'PostgreSQL can transform them into joins (semi-join, anti-join) during planning, achieving the same efficiency', 'They use caching', 'They skip index scans'], correctAnswer: 1, explanation: 'The optimizer transforms many correlated subqueries (IN, EXISTS, NOT IN, NOT EXISTS) into semi-joins or anti-joins, which execute as efficiently as explicit joins.', tags: ['correlated', 'optimization', 'transformation'] },
  { id: 'pg-joins-l3-025', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'How do you find the shortest path between two nodes in a graph using a recursive CTE?', options: ['Using self-joins', 'BFS with recursive CTE: track path length, use UNION to eliminate revisited nodes, and stop at target', 'PostgreSQL cannot do graph queries', 'Only with external libraries'], correctAnswer: 1, explanation: 'Use a recursive CTE with BFS. Track the path and length. UNION (not UNION ALL) prevents revisiting nodes. Filter for the target node with minimum path length.', codeSnippet: 'WITH RECURSIVE paths AS (\n  SELECT target_id, ARRAY[source_id, target_id] AS path, 1 AS hops\n  FROM edges WHERE source_id = 1\n  UNION\n  SELECT e.target_id, p.path || e.target_id, p.hops + 1\n  FROM edges e JOIN paths p ON e.source_id = p.target_id\n  WHERE NOT e.target_id = ANY(p.path) AND p.hops < 10\n)\nSELECT * FROM paths WHERE target_id = 42 ORDER BY hops LIMIT 1;', tags: ['recursive-cte', 'shortest-path', 'bfs'] },
  { id: 'pg-joins-l3-026', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL', question: 'How does LATERAL help with "unpivoting" data?', options: ['It cannot help with unpivoting', 'LATERAL with VALUES can turn columns into rows', 'Using PIVOT function', 'Using UNION only'], correctAnswer: 1, explanation: 'LATERAL with VALUES(...) AS t(col) turns multiple columns from each row into separate rows (unpivot), which is cleaner than multiple UNION ALL statements.', codeSnippet: 'SELECT s.id, v.quarter, v.revenue\nFROM sales s,\nLATERAL (\n  VALUES\n    (\'Q1\', s.q1_revenue),\n    (\'Q2\', s.q2_revenue),\n    (\'Q3\', s.q3_revenue),\n    (\'Q4\', s.q4_revenue)\n) AS v(quarter, revenue);', tags: ['lateral', 'unpivot', 'values'] },
  { id: 'pg-joins-l3-027', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'What is a "temporal join" and how do you implement it in PostgreSQL?', options: ['A time-based CROSS JOIN', 'Joining records based on overlapping or point-in-time date ranges using range operators', 'Using TIMESTAMP columns only', 'A historical data merge'], correctAnswer: 1, explanation: 'Temporal joins match records where time periods overlap. PostgreSQL range types (tsrange) and the && (overlap) operator make this efficient, especially with GiST indexes.', codeSnippet: 'SELECT e.name, r.rate\nFROM employees e\nJOIN salary_rates r\n  ON e.id = r.employee_id\n  AND e.hire_date <@ r.effective_range;', tags: ['temporal-join', 'range', 'overlap'] },
  { id: 'pg-joins-l3-028', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery Optimization', question: 'What is the difference between a "correlated" and "uncorrelated" subquery in terms of optimization?', options: ['No difference', 'Uncorrelated subqueries are evaluated once; correlated are evaluated per-row (though the optimizer may transform them)', 'Correlated subqueries are faster', 'Uncorrelated are always slower'], correctAnswer: 1, explanation: 'Uncorrelated subqueries compute their result once and reuse it. Correlated subqueries conceptually run per outer row but may be optimized into joins by the planner.', tags: ['correlated', 'uncorrelated', 'evaluation'] },
  { id: 'pg-joins-l3-029', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'CTE', question: 'What is a "search" CTE (PostgreSQL 14+)?', options: ['A CTE for full-text search', 'A recursive CTE with the SEARCH clause that orders results in breadth-first or depth-first order', 'A CTE with WHERE clause', 'A CTE for index searches'], correctAnswer: 1, explanation: 'PostgreSQL 14 added SEARCH BREADTH FIRST BY col and SEARCH DEPTH FIRST BY col to recursive CTEs, automatically generating an ordering column.', tags: ['search-cte', 'postgresql-14', 'traversal-order'] },
  { id: 'pg-joins-l3-030', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you implement a "greatest-n-per-group" query efficiently?', options: ['Using GROUP BY with MAX', 'DISTINCT ON + ORDER BY, or LATERAL with ORDER BY LIMIT N, or ROW_NUMBER() window function', 'Using CROSS JOIN', 'Using FULL JOIN'], correctAnswer: 1, explanation: 'For top-1: DISTINCT ON is simplest. For top-N: LATERAL is most efficient with an index. ROW_NUMBER() works but scans all rows.', codeSnippet: '-- Top 3 orders per customer using LATERAL:\nSELECT c.id, c.name, t.order_id, t.amount\nFROM customers c\nLEFT JOIN LATERAL (\n  SELECT id AS order_id, amount\n  FROM orders WHERE customer_id = c.id\n  ORDER BY amount DESC LIMIT 3\n) t ON TRUE;', tags: ['top-n-per-group', 'lateral', 'distinct-on'] },
  { id: 'pg-joins-l3-031', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'What is a "derived column" or "lateral column alias" in PostgreSQL?', options: ['A column from a derived table', 'PostgreSQL does not support lateral column aliases; you cannot reference a column alias in the same SELECT level', 'A column defined in LATERAL', 'An alias from a CTE'], correctAnswer: 1, explanation: 'Unlike some databases, PostgreSQL does not support lateral column aliases (referencing a SELECT alias in the same SELECT clause). Use a subquery or CTE to reference computed columns.', codeSnippet: '-- This FAILS in PostgreSQL:\nSELECT x + 1 AS y, y * 2 AS z FROM t;\n\n-- Use a subquery instead:\nSELECT y, y * 2 AS z\nFROM (SELECT x + 1 AS y FROM t) sub;', tags: ['lateral-alias', 'limitation', 'workaround'] },
  { id: 'pg-joins-l3-032', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you perform an "asof join" (point-in-time lookup) in PostgreSQL?', options: ['Using a built-in ASOF keyword', 'Using LATERAL with ORDER BY timestamp DESC LIMIT 1 to find the closest preceding record', 'Using temporal tables', 'Using BETWEEN only'], correctAnswer: 1, explanation: 'An asof join finds the most recent record at or before a given point in time. LATERAL with ORDER BY ... DESC LIMIT 1 is the standard PostgreSQL pattern.', codeSnippet: 'SELECT t.timestamp, t.symbol,\n  q.price AS latest_price\nFROM trades t\nLEFT JOIN LATERAL (\n  SELECT price FROM quotes\n  WHERE symbol = t.symbol AND timestamp <= t.timestamp\n  ORDER BY timestamp DESC LIMIT 1\n) q ON TRUE;', tags: ['asof-join', 'lateral', 'point-in-time'] },
  { id: 'pg-joins-l3-033', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'How do you compute a transitive closure using a recursive CTE?', options: ['Using self-joins', 'Start with direct relationships, then recursively add indirect connections', 'Using FULL JOIN', 'It is not possible in SQL'], correctAnswer: 1, explanation: 'The transitive closure finds all reachable nodes. The anchor provides direct edges, and the recursive step extends paths by one hop.', tags: ['transitive-closure', 'recursive-cte', 'graph'] },
  { id: 'pg-joins-l3-034', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'What does "hash join batching" mean in EXPLAIN output?', options: ['Running hash joins in parallel', 'Splitting the hash table into multiple batches because it exceeds work_mem, processing each batch separately', 'Batching multiple queries', 'A network batch operation'], correctAnswer: 1, explanation: 'When the inner relation exceeds work_mem, PostgreSQL partitions it into batches. The first batch stays in memory; the rest are written to temp files and processed in subsequent passes.', tags: ['hash-join', 'batching', 'work-mem'] },
  { id: 'pg-joins-l3-035', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Memoize', question: 'When does the Memoize plan node help with nested loop joins?', options: ['Always', 'When the inner side is parameterized and many outer rows share the same parameter value (high cache hit rate)', 'When the inner side is large', 'When there is no index'], correctAnswer: 1, explanation: 'Memoize caches results of parameterized inner scans. If the outer side has many duplicate join key values, the cache hit rate is high and performance improves significantly.', tags: ['memoize', 'nested-loop', 'caching'] },
  { id: 'pg-joins-l3-036', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'What is the performance difference between IN (list) and IN (subquery)?', options: ['IN with a list is always faster', 'For large lists, a subquery backed by an index can be faster because the planner can choose a semi-join strategy', 'They are always equivalent', 'IN with subquery is always slower'], correctAnswer: 1, explanation: 'A large IN list creates a constant filter. A subquery can use indexes and join strategies. For very large value sets, using a temporary table or CTE with a join is often most efficient.', tags: ['in', 'performance', 'list-vs-subquery'] },
  { id: 'pg-joins-l3-037', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'EXISTS vs JOIN', question: 'When does EXISTS outperform INNER JOIN?', options: ['Always', 'When you only need to check existence without retrieving data from the joined table, as EXISTS short-circuits', 'Never — JOIN is always better', 'For small tables only'], correctAnswer: 1, explanation: 'EXISTS returns TRUE on the first match without scanning all matches. INNER JOIN produces a row for each match. For one-to-many where you only need the "one" side, EXISTS avoids row multiplication.', tags: ['exists', 'inner-join', 'short-circuit'] },
  { id: 'pg-joins-l3-038', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'CTE', question: 'What is the performance implication of referencing a CTE multiple times when it is NOT MATERIALIZED?', options: ['No impact', 'The CTE query may be executed multiple times, once for each reference, potentially doubling work', 'It is always cached after first execution', 'It causes an error'], correctAnswer: 1, explanation: 'With NOT MATERIALIZED (default since PG 12), the CTE is inlined. If referenced multiple times, the underlying query may execute multiple times. Use MATERIALIZED to compute once.', tags: ['cte', 'multiple-references', 'performance'] },
  { id: 'pg-joins-l3-039', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you efficiently join on a function result?', options: ['Join using WHERE', 'Use a functional index or LATERAL to avoid repeated function evaluation per comparison', 'Functions cannot be used in joins', 'Using CASE in ON clause'], correctAnswer: 1, explanation: 'If the join condition involves a function (e.g., ON LOWER(a.col) = LOWER(b.col)), create functional indexes on both sides. Or use LATERAL to compute once per row.', codeSnippet: 'CREATE INDEX idx_lower_email ON users (LOWER(email));\n\nSELECT * FROM users u\nJOIN invites i ON LOWER(u.email) = LOWER(i.email);', tags: ['functional-index', 'join', 'function'] },
  { id: 'pg-joins-l3-040', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'What is the maximum recursion depth in PostgreSQL\'s recursive CTEs?', options: ['100', '1000', 'There is no built-in limit; you must add your own safety check', '10000'], correctAnswer: 2, explanation: 'PostgreSQL does not have a built-in recursion limit. Infinite recursion will run until it is cancelled or exhausts resources. Always add a depth counter or use CYCLE detection.', tags: ['recursive-cte', 'depth-limit', 'safety'] },
  { id: 'pg-joins-l3-041', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL', question: 'How does the planner handle LATERAL with an index on the inner table?', options: ['It ignores the index', 'It can use a nested loop with an index scan on the inner side, making LATERAL very efficient', 'It always uses hash join', 'LATERAL prevents index usage'], correctAnswer: 1, explanation: 'LATERAL naturally pairs with nested loop joins. For each outer row, the lateral subquery can use an index scan on the inner table, making it very efficient for per-row lookups.', tags: ['lateral', 'index', 'nested-loop'] },
  { id: 'pg-joins-l3-042', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you find "islands" (consecutive groups) of rows in a sequence?', options: ['Using GROUP BY', 'Subtract ROW_NUMBER from the sequential column to create group identifiers, then GROUP BY the group', 'Using DISTINCT', 'Using UNION'], correctAnswer: 1, explanation: 'The islands-and-gaps technique uses the difference between a value and ROW_NUMBER to identify consecutive groups. Rows in the same island get the same group identifier.', codeSnippet: 'WITH grouped AS (\n  SELECT date, status,\n    date - (ROW_NUMBER() OVER (PARTITION BY status ORDER BY date))::INT AS grp\n  FROM events\n)\nSELECT status, MIN(date) AS start_date, MAX(date) AS end_date\nFROM grouped GROUP BY status, grp ORDER BY start_date;', tags: ['islands-gaps', 'row-number', 'consecutive'] },
  { id: 'pg-joins-l3-043', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'How do you use a subquery in a CHECK constraint?', options: ['CHECK constraints support subqueries', 'CHECK constraints cannot contain subqueries; use triggers or exclusion constraints instead', 'Only with scalar subqueries', 'Only in PostgreSQL 15+'], correctAnswer: 1, explanation: 'CHECK constraints cannot reference other tables or contain subqueries. For cross-table validation, use triggers, foreign keys, or exclusion constraints.', tags: ['check-constraint', 'subquery', 'limitation'] },
  { id: 'pg-joins-l3-044', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'What does the "enable_hashjoin" setting do?', options: ['Enables hash tables', 'When set to off, discourages (but does not prevent) the planner from using hash joins', 'Enables hashing of passwords', 'Creates hash indexes'], correctAnswer: 1, explanation: 'Setting enable_hashjoin = off makes hash joins very expensive in the cost model so the planner avoids them. Useful for debugging plan issues but not recommended for production.', tags: ['enable-hashjoin', 'planner', 'debugging'] },
  { id: 'pg-joins-l3-045', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you implement a "fuzzy join" (approximate matching)?', options: ['Using = operator', 'Using similarity functions (pg_trgm), SOUNDEX, or Levenshtein distance with a threshold in the join condition', 'Fuzzy joins are not possible in SQL', 'Using LIKE only'], correctAnswer: 1, explanation: 'Install pg_trgm extension and use similarity(), word_similarity(), or the % operator in join conditions. GIN/GiST indexes on trigrams make this efficient.', codeSnippet: 'CREATE EXTENSION IF NOT EXISTS pg_trgm;\n\nSELECT a.name, b.name, similarity(a.name, b.name) AS sim\nFROM companies a\nJOIN suppliers b\n  ON similarity(a.name, b.name) > 0.5;', tags: ['fuzzy-join', 'pg-trgm', 'similarity'] },
  { id: 'pg-joins-l3-046', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'CTE', question: 'How do you use a CTE to implement pagination with total count in a single query?', options: ['Two separate queries are required', 'Use a CTE for the base query, reference it once for COUNT(*) and once for the page of rows', 'Using OFFSET only', 'Using a window function COUNT(*) OVER()'], correctAnswer: 3, explanation: 'The most efficient approach is COUNT(*) OVER() as a window function in the query, which provides total count with each row. CTE approach works but may compute the base query twice.', codeSnippet: 'SELECT *, COUNT(*) OVER() AS total_count\nFROM users\nWHERE active = true\nORDER BY name\nLIMIT 20 OFFSET 40;', tags: ['pagination', 'total-count', 'window-function'] },
  { id: 'pg-joins-l3-047', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'What is a "range merge join" and when is it useful?', options: ['Merging two range types', 'A merge join applied to range overlap conditions, efficient when both sides are sorted by range boundaries', 'A merge of range partitions', 'A PostgreSQL-specific join type'], correctAnswer: 1, explanation: 'For range-based joins (WHERE a.start < b.end AND a.end > b.start), merge join can be efficient if both tables are sorted. GiST indexes with range types often perform better.', tags: ['range-merge-join', 'range-types', 'overlap'] },
  { id: 'pg-joins-l3-048', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'What is the impact of volatile functions in subqueries on optimization?', options: ['No impact', 'Volatile functions prevent the optimizer from caching subquery results or flattening subqueries into joins', 'They make subqueries faster', 'They cause errors'], correctAnswer: 1, explanation: 'Volatile functions (like random(), now() in some contexts) prevent the optimizer from evaluating subqueries once and reusing results. The subquery may need to be re-evaluated.', tags: ['volatile', 'optimization', 'subquery'] },
  { id: 'pg-joins-l3-049', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'How do you accumulate a path string in a recursive CTE?', options: ['Using GROUP_CONCAT', 'Using array concatenation (path || ARRAY[node]) or string concatenation (path || \'/\' || name)', 'Using LISTAGG', 'Using STRING_AGG inside the recursive term'], correctAnswer: 1, explanation: 'Build the path using array append (||) or string concatenation in the recursive term. Arrays are generally safer (no delimiter conflicts) and easier to check for cycles.', codeSnippet: 'WITH RECURSIVE path AS (\n  SELECT id, name, ARRAY[name]::TEXT[] AS path_names\n  FROM nodes WHERE id = 1\n  UNION ALL\n  SELECT n.id, n.name, p.path_names || n.name\n  FROM nodes n JOIN path p ON n.parent_id = p.id\n)\nSELECT id, array_to_string(path_names, \' > \') AS breadcrumb\nFROM path;', tags: ['recursive-cte', 'path', 'accumulation'] },
  { id: 'pg-joins-l3-050', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you implement a "window join" (joining rows within a time window)?', options: ['Using WINDOW clause', 'Join with a range condition like ON a.timestamp BETWEEN b.timestamp - interval \'1 hour\' AND b.timestamp', 'Using LAG/LEAD', 'Window joins are not possible'], correctAnswer: 1, explanation: 'A window join matches rows from two tables where timestamps fall within a specified range. An index on the timestamp column makes this efficient.', codeSnippet: 'SELECT a.*, b.*\nFROM events a\nJOIN metrics b\n  ON a.device_id = b.device_id\n  AND b.timestamp BETWEEN a.timestamp - INTERVAL \'5 minutes\'\n                      AND a.timestamp + INTERVAL \'5 minutes\';', tags: ['window-join', 'time-range', 'temporal'] },
  { id: 'pg-joins-l3-051', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'CTE', question: 'Can you use RETURNING from multiple writable CTEs in the same statement?', options: ['No, only one CTE can have RETURNING', 'Yes, each writable CTE can have RETURNING and the results can be used by subsequent CTEs or the final statement', 'Only the last CTE', 'Only with INSERT'], correctAnswer: 1, explanation: 'Each writable CTE can have its own RETURNING clause. The returned rows can be referenced by later CTEs or the main statement.', codeSnippet: 'WITH\n  del AS (DELETE FROM temp_import RETURNING *),\n  ins AS (INSERT INTO orders SELECT * FROM del RETURNING id)\nSELECT COUNT(*) FROM ins;', tags: ['writable-cte', 'returning', 'chaining'] },
  { id: 'pg-joins-l3-052', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'What is "right-hand-side" restriction in outer join reordering?', options: ['A syntax restriction', 'The optimizer cannot freely reorder outer joins; it must preserve the semantics of which side is "preserved"', 'Right joins cannot be reordered', 'A PostgreSQL-specific limitation'], correctAnswer: 1, explanation: 'Unlike inner joins, outer joins are not freely commutative or associative. The planner must preserve the outer join semantics (which table is preserved), limiting reordering options.', tags: ['outer-join', 'reordering', 'limitation'] },
  { id: 'pg-joins-l3-053', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'How does PostgreSQL handle a subquery that appears in both the SELECT list and WHERE clause?', options: ['It runs twice', 'The optimizer may extract and evaluate it once, then reuse the result', 'It always runs once', 'It causes an error'], correctAnswer: 1, explanation: 'PostgreSQL may or may not share subquery evaluation. For identical uncorrelated subqueries, the planner often evaluates once. For correlated subqueries, it depends on the transformation.', tags: ['subquery', 'cse', 'optimization'] },
  { id: 'pg-joins-l3-054', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL', question: 'Can LATERAL be used with DELETE or UPDATE?', options: ['Yes, directly', 'No, but you can achieve similar results using USING (DELETE) or FROM (UPDATE) with subqueries', 'Only with CTEs', 'LATERAL is only for SELECT'], correctAnswer: 1, explanation: 'LATERAL is a FROM clause feature for SELECT. DELETE uses USING and UPDATE uses FROM for similar join-based operations. CTEs with LATERAL in SELECT can feed DML.', tags: ['lateral', 'dml', 'using-from'] },
  { id: 'pg-joins-l3-055', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you perform a "band join" (range-overlapping join) efficiently?', options: ['Using BETWEEN in ON', 'Use range types with GiST indexes and the && operator for efficient overlap checks', 'Using hash join', 'Using merge join only'], correctAnswer: 1, explanation: 'PostgreSQL range types (int4range, daterange, etc.) with GiST indexes support efficient overlap (&&), contains (@>), and other range operations in join conditions.', codeSnippet: 'CREATE INDEX ON reservations USING GIST (during);\n\nSELECT a.*, b.*\nFROM reservations a\nJOIN reservations b\n  ON a.room_id = b.room_id\n  AND a.during && b.during\n  AND a.id < b.id;', tags: ['band-join', 'range-types', 'gist'] },
  { id: 'pg-joins-l3-056', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'How can you paginate through a recursive CTE result?', options: ['Using LIMIT/OFFSET on the recursive term', 'Apply LIMIT/OFFSET to the outer SELECT that queries the CTE, not inside the CTE itself', 'Recursion does not support pagination', 'Using FETCH NEXT'], correctAnswer: 1, explanation: 'The recursive CTE computes the full result. Pagination (LIMIT/OFFSET or keyset) is applied to the outer query. LIMIT inside the recursive term limits recursion depth, not pagination.', tags: ['recursive-cte', 'pagination', 'limit'] },
  { id: 'pg-joins-l3-057', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'How does work_mem affect join performance?', options: ['It only affects sorting', 'Higher work_mem allows larger hash tables (fewer batches) and larger sort buffers for merge joins, improving join speed', 'It only affects WHERE filtering', 'No effect on joins'], correctAnswer: 1, explanation: 'work_mem is allocated per sort or hash operation. Larger work_mem means hash joins can fit more data in memory and merge joins can sort faster, both reducing I/O.', tags: ['work-mem', 'hash-join', 'merge-join'] },
  { id: 'pg-joins-l3-058', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'What is "predicate pushdown" and how does it affect subquery performance?', options: ['Pushing WHERE into GROUP BY', 'The optimizer pushes filter conditions from the outer query into subqueries/CTEs to filter rows earlier, reducing I/O', 'Moving predicates to the end', 'A manual optimization technique only'], correctAnswer: 1, explanation: 'Predicate pushdown moves WHERE conditions into subqueries so they filter rows early. This reduces the data processed by joins and aggregations. NOT MATERIALIZED CTEs allow this.', tags: ['predicate-pushdown', 'optimization', 'subquery'] },
  { id: 'pg-joins-l3-059', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you handle a "polymorphic association" join where a foreign key can reference different tables?', options: ['A single JOIN', 'LEFT JOIN each possible target table with a type discriminator column', 'It is not possible in SQL', 'Using FULL JOIN'], correctAnswer: 1, explanation: 'Polymorphic associations use a type column (e.g., commentable_type) and an id column. JOIN each target table with a condition on the type discriminator.', codeSnippet: 'SELECT c.*,\n  COALESCE(p.title, a.title) AS target_title\nFROM comments c\nLEFT JOIN posts p\n  ON c.commentable_type = \'Post\' AND c.commentable_id = p.id\nLEFT JOIN articles a\n  ON c.commentable_type = \'Article\' AND c.commentable_id = a.id;', tags: ['polymorphic', 'discriminator', 'left-join'] },
  { id: 'pg-joins-l3-060', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'What is a "deduplication join" and how do you implement it?', options: ['A join that removes duplicates', 'Using DISTINCT ON or ROW_NUMBER() to pick one row per key before joining, preventing row multiplication', 'Using UNION', 'A special join type'], correctAnswer: 1, explanation: 'Pre-deduplicating one side of a join prevents row multiplication. Use DISTINCT ON in a subquery or CTE before joining.', codeSnippet: 'WITH latest_status AS (\n  SELECT DISTINCT ON (order_id)\n    order_id, status, updated_at\n  FROM order_status_log\n  ORDER BY order_id, updated_at DESC\n)\nSELECT o.*, ls.status\nFROM orders o\nJOIN latest_status ls ON o.id = ls.order_id;', tags: ['deduplication', 'distinct-on', 'pre-process'] },
  { id: 'pg-joins-l3-061', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'Can a recursive CTE be used inside a VIEW?', options: ['No, views cannot contain recursive CTEs', 'Yes, recursive CTEs can be part of a view definition', 'Only materialized views', 'Only with SECURITY DEFINER'], correctAnswer: 1, explanation: 'Recursive CTEs can be used in view definitions. The recursion executes each time the view is queried.', tags: ['recursive-cte', 'view', 'definition'] },
  { id: 'pg-joins-l3-062', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL', question: 'Can you use LATERAL with a materialized view?', options: ['No', 'Yes, LATERAL can reference any table, view, or materialized view in the FROM clause', 'Only with regular views', 'Only with CTEs'], correctAnswer: 1, explanation: 'LATERAL can reference columns from any preceding FROM item regardless of whether it is a table, view, materialized view, or another subquery.', tags: ['lateral', 'materialized-view', 'compatibility'] },
  { id: 'pg-joins-l3-063', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'What is the "pre-aggregate then join" pattern?', options: ['Aggregating after joining', 'Computing aggregates in a subquery/CTE first, then joining the summary to other tables to avoid row multiplication', 'Joining then aggregating', 'A PostgreSQL-specific pattern'], correctAnswer: 1, explanation: 'When joining a parent table to multiple child tables, aggregate each child table separately first, then join the summaries. This avoids the Cartesian product between children.', tags: ['pre-aggregate', 'join-pattern', 'row-multiplication'] },
  { id: 'pg-joins-l3-064', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'How does the optimizer handle a subquery with DISTINCT in a semi-join context?', options: ['It keeps the DISTINCT', 'It can remove the DISTINCT because semi-joins only need to know if any row exists, not all distinct rows', 'DISTINCT prevents optimization', 'It converts to UNION'], correctAnswer: 1, explanation: 'The optimizer can remove DISTINCT from a subquery used with IN or EXISTS because the semi-join semantics only check for existence, making deduplication unnecessary.', tags: ['distinct', 'semi-join', 'optimization'] },
  { id: 'pg-joins-l3-065', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'CTE', question: 'How do you use a CTE to implement "soft delete with cascade"?', options: ['Using DELETE CASCADE', 'Writable CTE: first CTE soft-deletes parent, RETURNING ids, second CTE soft-deletes children using those ids', 'Using triggers only', 'Using ON DELETE SET NULL'], correctAnswer: 1, explanation: 'Writable CTEs chain operations. Delete the parent (or update to set deleted_at), return IDs, and use those IDs to update child records.', codeSnippet: 'WITH soft_del_users AS (\n  UPDATE users SET deleted_at = NOW()\n  WHERE id = 42 RETURNING id\n),\nsoft_del_orders AS (\n  UPDATE orders SET deleted_at = NOW()\n  WHERE user_id IN (SELECT id FROM soft_del_users)\n  RETURNING id\n)\nSELECT COUNT(*) FROM soft_del_orders;', tags: ['writable-cte', 'soft-delete', 'cascade'] },
  { id: 'pg-joins-l3-066', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'What is the "exclusive arc" anti-pattern in schema design and how does it affect joins?', options: ['A circular reference', 'A row with multiple nullable foreign keys where exactly one should be non-NULL, requiring multiple LEFT JOINs and COALESCE', 'A self-referencing table', 'A missing index'], correctAnswer: 1, explanation: 'Exclusive arcs have mutually exclusive FKs (e.g., post_id OR article_id). Queries need LEFT JOIN + COALESCE. Better design uses polymorphic associations or inheritance.', tags: ['exclusive-arc', 'anti-pattern', 'schema-design'] },
  { id: 'pg-joins-l3-067', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'What is a "non-correlated scalar subquery" and how is it optimized?', options: ['A subquery that returns multiple rows', 'A scalar subquery with no outer references, computed once and cached for all rows', 'A subquery in FROM', 'A subquery returning a table'], correctAnswer: 1, explanation: 'A non-correlated scalar subquery has no references to the outer query. PostgreSQL evaluates it once and uses the cached result for all outer rows, making it very efficient.', tags: ['scalar-subquery', 'uncorrelated', 'caching'] },
  { id: 'pg-joins-l3-068', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL', question: 'How do you use LATERAL to implement a "running difference" between consecutive rows?', options: ['Using self-join', 'LATERAL with a subquery that looks back one row using ORDER BY DESC LIMIT 1', 'Using window functions only', 'Using EXCEPT'], correctAnswer: 1, explanation: 'LATERAL can look back to the previous row. However, LAG() window function is usually more efficient and readable for this use case.', codeSnippet: 'SELECT s.date, s.value,\n  s.value - prev.value AS diff\nFROM sensor_data s\nLEFT JOIN LATERAL (\n  SELECT value FROM sensor_data\n  WHERE date < s.date ORDER BY date DESC LIMIT 1\n) prev ON TRUE\nORDER BY s.date;', tags: ['lateral', 'running-difference', 'consecutive'] },
  { id: 'pg-joins-l3-069', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you handle the "entity-attribute-value" (EAV) pattern with joins?', options: ['A single JOIN', 'Multiple self-joins or LATERAL joins to pivot attributes into columns, or use JSONB aggregation', 'EAV cannot be queried', 'Using UNION only'], correctAnswer: 1, explanation: 'EAV tables require pivoting. Each attribute needs a separate LEFT JOIN or a filtered aggregate. JSONB or crosstab are more efficient alternatives.', codeSnippet: 'SELECT e.id,\n  MAX(CASE WHEN a.key = \'color\' THEN a.value END) AS color,\n  MAX(CASE WHEN a.key = \'size\' THEN a.value END) AS size\nFROM entities e\nLEFT JOIN attributes a ON e.id = a.entity_id\nGROUP BY e.id;', tags: ['eav', 'pivot', 'conditional-aggregate'] },
  { id: 'pg-joins-l3-070', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'What is "join removal" for LEFT JOINs?', options: ['Removing LEFT JOINs for performance', 'The optimizer removes a LEFT JOIN when the joined table contributes no columns to the result and has a unique constraint on the join key', 'Converting LEFT to INNER', 'Removing duplicate joins'], correctAnswer: 1, explanation: 'If a LEFT JOIN\'s right table has a unique constraint on the join column and no columns from it appear in SELECT, WHERE, or ORDER BY, the optimizer can safely remove the entire join.', tags: ['join-removal', 'left-join', 'optimization'] },
  { id: 'pg-joins-l3-071', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'How do you compute cumulative subtree sizes in a recursive CTE?', options: ['Using SUM directly', 'Two passes: first recurse to build the tree, then a second CTE or query aggregates bottom-up', 'Using COUNT in the recursive term', 'It requires procedural code'], correctAnswer: 1, explanation: 'Recursive CTEs process top-down. For bottom-up aggregation (subtree sizes), first build the tree with the recursive CTE, then use a separate aggregation step or a bottom-up recursive approach.', tags: ['recursive-cte', 'subtree', 'aggregation'] },
  { id: 'pg-joins-l3-072', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL', question: 'How does LATERAL perform with a large outer table?', options: ['Always efficient', 'Performance depends on the inner scan efficiency; with an index, LATERAL uses nested loop index scans which are O(N * log M)', 'Always slow', 'It depends only on the inner table size'], correctAnswer: 1, explanation: 'LATERAL with nested loop + index scan is O(N * log M) where N is outer rows and M is inner table size. Without an index, it degrades to O(N * M). Index quality is critical.', tags: ['lateral', 'performance', 'complexity'] },
  { id: 'pg-joins-l3-073', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'How does PostgreSQL evaluate a subquery inside CASE WHEN?', options: ['It evaluates all subqueries eagerly', 'CASE short-circuits: if an earlier WHEN matches, later WHEN subqueries are not evaluated', 'Subqueries in CASE are not allowed', 'All branches are evaluated in parallel'], correctAnswer: 1, explanation: 'CASE uses short-circuit evaluation. If the first WHEN condition is true, subsequent WHEN clauses (and their subqueries) are never evaluated.', tags: ['case', 'short-circuit', 'subquery'] },
  { id: 'pg-joins-l3-074', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you efficiently implement a "nearest neighbor" join?', options: ['Using = operator', 'Using LATERAL with ORDER BY distance LIMIT 1 and a spatial index (GiST with point/geometry types)', 'Using CROSS JOIN with MIN', 'Not possible without extensions'], correctAnswer: 1, explanation: 'For spatial nearest-neighbor: use PostGIS or cube/point types with GiST indexes. LATERAL with ORDER BY <-> operator (distance) and LIMIT efficiently uses the index.', codeSnippet: 'SELECT s.name, nearest.name AS closest_store\nFROM stores s\nCROSS JOIN LATERAL (\n  SELECT w.name FROM warehouses w\n  ORDER BY s.location <-> w.location\n  LIMIT 1\n) nearest;', tags: ['nearest-neighbor', 'spatial', 'gist'] },
  { id: 'pg-joins-l3-075', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'CTE', question: 'What are the limitations of writable CTEs?', options: ['No limitations', 'They share the same snapshot (cannot see each other\'s changes), and the execution order of side effects is not guaranteed', 'They cannot use RETURNING', 'They cannot modify the same table'], correctAnswer: 1, explanation: 'Key limitations: 1) All CTEs share the same snapshot, 2) Side-effect order is undefined, 3) A CTE cannot reference a later CTE, 4) The same row should not be modified by multiple CTEs.', tags: ['writable-cte', 'limitations', 'snapshot'] },
  { id: 'pg-joins-l3-076', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'What is "join pushdown" to foreign tables?', options: ['Pushing data to foreign servers', 'The planner sends the entire join to the foreign server for execution, reducing network transfer', 'Joining foreign and local tables', 'A push notification system'], correctAnswer: 1, explanation: 'With PostgreSQL FDW (postgres_fdw), the planner can push joins between tables on the same foreign server to be executed remotely, avoiding transferring all rows over the network.', tags: ['fdw', 'join-pushdown', 'remote-execution'] },
  { id: 'pg-joins-l3-077', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'How do you implement a recursive CTE that processes a graph breadth-first?', options: ['It is always breadth-first', 'Use UNION (not UNION ALL) to prevent revisits and process level by level, or use SEARCH BREADTH FIRST (PG 14+)', 'Using ORDER BY depth', 'Using LIMIT per level'], correctAnswer: 1, explanation: 'Recursive CTEs naturally process in a working-table manner. SEARCH BREADTH FIRST BY col SET ord (PG 14+) adds an ordering column. Alternatively, track depth and ORDER BY it.', tags: ['recursive-cte', 'bfs', 'breadth-first'] },
  { id: 'pg-joins-l3-078', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'How does the optimizer handle EXISTS with a constant subquery like EXISTS (SELECT 1 WHERE false)?', options: ['It runs the subquery', 'It evaluates the constant expression at planning time and replaces EXISTS with TRUE or FALSE', 'It always returns TRUE', 'It causes a planning error'], correctAnswer: 1, explanation: 'The optimizer can evaluate constant expressions at planning time. EXISTS (SELECT 1 WHERE false) is simplified to FALSE, and the plan may skip the subquery entirely.', tags: ['exists', 'constant-folding', 'optimizer'] },
  { id: 'pg-joins-l3-079', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'What is the "median trick" using percentile_cont within a join?', options: ['Computing median of joined tables', 'Using percentile_cont in a LATERAL subquery or window to compute per-group medians alongside join results', 'A sorting technique', 'A PostgreSQL extension'], correctAnswer: 1, explanation: 'Combine LATERAL with percentile_cont for efficient per-group median computation alongside other join results, without needing separate subqueries.', codeSnippet: 'SELECT d.name, m.median_salary\nFROM departments d\nLEFT JOIN LATERAL (\n  SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY salary) AS median_salary\n  FROM employees WHERE dept_id = d.id\n) m ON TRUE;', tags: ['median', 'lateral', 'per-group'] },
  { id: 'pg-joins-l3-080', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL', question: 'Can LATERAL be used with INSERT ... SELECT?', options: ['No, LATERAL is only for pure SELECT', 'Yes, LATERAL works in the SELECT portion of INSERT ... SELECT', 'Only with CTEs', 'Only with COPY'], correctAnswer: 1, explanation: 'The SELECT part of INSERT ... SELECT is a regular query that supports all features including LATERAL, JOINs, CTEs, etc.', tags: ['lateral', 'insert-select', 'dml'] },
  { id: 'pg-joins-l3-081', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'How do you join on computed expressions efficiently?', options: ['Always compute in the ON clause', 'Create expression indexes on the computed values so the planner can use index scans for the join', 'Pre-compute in a trigger', 'Using materialized views only'], correctAnswer: 1, explanation: 'Expression indexes (e.g., CREATE INDEX ON t (LOWER(col))) allow the planner to use index scans when joining on computed expressions, avoiding full table scans.', tags: ['expression-index', 'computed-join', 'performance'] },
  { id: 'pg-joins-l3-082', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Subquery', question: 'What is the "double aggregate" problem and how do CTEs solve it?', options: ['Aggregating twice on the same column', 'Needing to aggregate and then aggregate the result requires nesting; CTEs make this readable', 'A PostgreSQL bug', 'Using HAVING twice'], correctAnswer: 1, explanation: 'You cannot nest aggregates (e.g., MAX(AVG(salary))). A CTE computes the first aggregation, then the outer query computes the second on the CTE results.', codeSnippet: 'WITH dept_avgs AS (\n  SELECT department, AVG(salary) AS avg_sal\n  FROM employees GROUP BY department\n)\nSELECT MAX(avg_sal) AS highest_avg_salary\nFROM dept_avgs;', tags: ['double-aggregate', 'cte', 'nesting'] },
  { id: 'pg-joins-l3-083', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Recursive CTE', question: 'How do you compute "level" or "generation" number in a recursive CTE hierarchy?', options: ['Using COUNT', 'Start the anchor with level = 1 (or 0) and increment by 1 in each recursive step', 'Using RANK()', 'Using DEPTH keyword'], correctAnswer: 1, explanation: 'Add a level column initialized to 1 (or 0) in the anchor. The recursive term sets level = previous_level + 1. This naturally tracks the depth/generation.', tags: ['recursive-cte', 'level', 'generation'] },
  { id: 'pg-joins-l3-084', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Planning', question: 'What does the "rows removed by filter" information in EXPLAIN ANALYZE tell you about a join?', options: ['Rows deleted from the table', 'How many rows passed the join condition but were then filtered by additional WHERE conditions, suggesting a possible index improvement', 'Rows with NULL values', 'Total rows in the table'], correctAnswer: 1, explanation: 'High "rows removed by filter" after a join suggests the join returned many rows that were then discarded by WHERE. A more selective index or additional join condition could improve this.', tags: ['explain', 'rows-removed', 'optimization'] },
  { id: 'pg-joins-l3-085', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'CTE', question: 'How do you implement "insert if not exists, return existing or new" using CTEs?', options: ['Using ON CONFLICT only', 'Use a CTE chain: first SELECT existing, then INSERT ... ON CONFLICT DO NOTHING ... RETURNING, then UNION or COALESCE both results', 'Using MERGE', 'Two separate queries'], correctAnswer: 1, explanation: 'The pattern uses writable CTEs: a SELECT CTE for existing rows, an INSERT CTE with ON CONFLICT DO NOTHING RETURNING for new rows, and a final query combining both.', codeSnippet: 'WITH\n  existing AS (\n    SELECT id FROM users WHERE email = \'a@b.com\'\n  ),\n  inserted AS (\n    INSERT INTO users (email) VALUES (\'a@b.com\')\n    ON CONFLICT (email) DO NOTHING\n    RETURNING id\n  )\nSELECT id FROM existing\nUNION ALL\nSELECT id FROM inserted;', tags: ['upsert', 'cte', 'return-existing'] },
  { id: 'pg-joins-l3-086', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'Join Techniques', question: 'What is the "semi-join reduction" optimization?', options: ['Reducing the number of semi-joins', 'Using a semi-join (EXISTS/IN) to pre-filter a large table before performing an expensive join with another table', 'Reducing join columns', 'A hash table optimization'], correctAnswer: 1, explanation: 'When a large table would produce many non-matching rows in a subsequent expensive join, a semi-join filter first reduces the input, making the expensive join faster.', tags: ['semi-join-reduction', 'optimization', 'pre-filter'] },
  { id: 'pg-joins-l3-087', language: 'postgresql', level: 'level3', category: 'JOINs & Subqueries', subcategory: 'LATERAL', question: 'How does PostgreSQL handle LATERAL when the outer table is very large and the inner table is small?', options: ['LATERAL is always slow with large outer tables', 'The planner may choose a hash join or materialized inner scan instead of nested loop, depending on cost estimates', 'It switches to CROSS JOIN', 'It limits the outer table scan'], correctAnswer: 1, explanation: 'Even with LATERAL, the planner considers multiple strategies. For a small inner table that fits in memory, it may use a hash or nested loop with Memoize for efficiency.', tags: ['lateral', 'large-outer', 'planner'] },
];

